mkdir -p /app/output/assets && cat > /app/output/assets/styles.css <<'EOF'
:root {
  --gb-green-900: #123524;
  --gb-green-700: #1f5b3d;
  --gb-green-600: #2d6a4f;
  --gb-green-500: #3a7d5a;
  --gb-cream-50: #fdfaf4;
  --gb-cream-100: #f7f1e3;
  --gb-cream-200: #ede3cc;
  --gb-brown-900: #3f2a1f;
  --gb-brown-700: #6b4a3a;
  --gb-brown-500: #8c6a56;
  --gb-text: #1f2a24;
  --gb-muted: #5e685f;
  --gb-border: #e3dac6;
  --shadow-soft: 0 8px 24px rgba(18, 53, 36, 0.08);
  --shadow-card: 0 10px 24px rgba(63, 42, 31, 0.08);
  --radius-xl: 22px;
  --radius-lg: 16px;
  --radius-md: 12px;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--gb-text);
  background: linear-gradient(180deg, var(--gb-cream-50) 0%, #fff 60%);
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
.container { width: min(1160px, calc(100% - 2.5rem)); margin: 0 auto; }
.section { padding: 4rem 0; }
.h1, .h2, .h3 { font-family: 'DM Sans', 'Inter', sans-serif; margin: 0; color: var(--gb-green-900); }
.h1 { font-size: clamp(2rem, 4vw, 3.5rem); line-height: 1.08; }
.h2 { font-size: clamp(1.55rem, 2.5vw, 2.25rem); line-height: 1.15; }
.h3 { font-size: clamp(1.1rem, 1.6vw, 1.35rem); }
.lead { color: var(--gb-muted); font-size: 1.06rem; line-height: 1.65; }
.muted { color: var(--gb-muted); }

.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(253, 250, 244, 0.9);
  border-bottom: 1px solid rgba(227, 218, 198, 0.7);
  backdrop-filter: blur(10px);
}
.nav-wrap { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 0.85rem 0; }
.brand { display: flex; align-items: center; gap: 0.75rem; font-weight: 800; color: var(--gb-green-900); }
.brand-mark {
  width: 38px; height: 38px; border-radius: 12px;
  background: radial-gradient(circle at 25% 25%, #5ea97e, var(--gb-green-700));
  display: grid; place-items: center; color: #fff; font-size: 1.1rem;
  box-shadow: var(--shadow-soft);
}
.nav-links { display: flex; gap: 1.1rem; align-items: center; }
.nav-links a { padding: 0.55rem 0.78rem; border-radius: 999px; color: var(--gb-muted); font-weight: 600; }
.nav-links a:hover, .nav-links a[aria-current='page'] { background: var(--gb-cream-100); color: var(--gb-green-900); }
.header-actions { display: flex; gap: 0.65rem; align-items: center; }
.mobile-toggle { display: none; }

.btn {
  border: 0; border-radius: 999px; cursor: pointer;
  font-weight: 700; padding: 0.75rem 1.15rem; font-size: 0.95rem;
  transition: 0.2s ease; display: inline-flex; align-items: center; gap: 0.45rem;
}
.btn-primary { background: var(--gb-green-700); color: #fff; box-shadow: var(--shadow-soft); }
.btn-primary:hover { background: var(--gb-green-600); transform: translateY(-1px); }
.btn-soft { background: var(--gb-cream-100); color: var(--gb-brown-900); }
.btn-soft:hover { background: var(--gb-cream-200); }
.btn-outline { background: #fff; color: var(--gb-green-700); border: 1px solid var(--gb-border); }

.hero {
  display: grid; gap: 2rem; grid-template-columns: 1.12fr 0.88fr; align-items: center;
}
.hero-card {
  border-radius: var(--radius-xl);
  background: linear-gradient(140deg, #fff 0%, var(--gb-cream-50) 100%);
  border: 1px solid var(--gb-border);
  box-shadow: var(--shadow-card);
  padding: clamp(1.4rem, 2.8vw, 2.4rem);
}
.hero-media {
  border-radius: var(--radius-xl);
  min-height: 390px;
  background: linear-gradient(155deg, rgba(46, 106, 79, 0.82), rgba(63, 42, 31, 0.45)), url('https://images.unsplash.com/photo-1447933601403-0c6688de566e?auto=format&fit=crop&w=1200&q=80') center/cover;
  box-shadow: var(--shadow-card);
}

.grid { display: grid; gap: 1.15rem; }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.card {
  background: #fff; border: 1px solid var(--gb-border); border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card); overflow: hidden;
}
.card-body { padding: 1.1rem 1.1rem 1.2rem; }
.pill { display: inline-block; border-radius: 999px; background: var(--gb-cream-100); color: var(--gb-brown-900); padding: 0.25rem 0.65rem; font-size: 0.77rem; font-weight: 700; }
.media-placeholder { height: 180px; background: linear-gradient(120deg, #b7d1c0, #e6d7bf); }

.page-title { padding: 2.6rem 0 1rem; }
.page-title p { max-width: 700px; }

.menu-layout { display: grid; grid-template-columns: 260px 1fr; gap: 1.25rem; }
.sidebar {
  position: sticky; top: 92px; align-self: start;
  background: #fff; border: 1px solid var(--gb-border); border-radius: var(--radius-lg);
  padding: 1rem;
}
.sidebar a { display: block; padding: 0.55rem 0.65rem; border-radius: 9px; color: var(--gb-muted); font-weight: 600; }
.sidebar a:hover { background: var(--gb-cream-100); color: var(--gb-green-900); }
.menu-category { margin-bottom: 1.8rem; }
.menu-items { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.9rem; }
.menu-item { border: 1px solid var(--gb-border); border-radius: var(--radius-md); padding: 0.9rem; background: #fff; }

.tabs { display: flex; flex-wrap: wrap; gap: 0.6rem; margin-top: 1.2rem; }
.tab-btn {
  border: 1px solid var(--gb-border); background: #fff; color: var(--gb-muted); border-radius: 999px;
  padding: 0.55rem 0.9rem; font-weight: 700; cursor: pointer;
}
.tab-btn.active { background: var(--gb-green-700); color: #fff; border-color: var(--gb-green-700); }
.tab-panel {
  margin-top: 1rem; background: #fff; border: 1px solid var(--gb-border);
  border-radius: var(--radius-lg); padding: 1.2rem;
}

.carousel { position: relative; }
.carousel-track-wrap { overflow: hidden; }
.carousel-track { display: flex; transition: transform 0.35s ease; }
.carousel-slide { min-width: 100%; display: grid; gap: 0.9rem; }
.carousel-controls { display: flex; gap: 0.55rem; }
.icon-btn {
  border: 1px solid var(--gb-border); background: #fff; width: 42px; height: 42px;
  border-radius: 50%; cursor: pointer; font-size: 1.2rem; color: var(--gb-green-900);
}

.search-shell {
  background: #fff; border: 1px solid var(--gb-border); border-radius: var(--radius-lg);
  padding: 1rem; box-shadow: var(--shadow-card);
}
.search-row { display: grid; grid-template-columns: 1fr auto auto; gap: 0.7rem; }
.input {
  border: 1px solid var(--gb-border); border-radius: 12px; padding: 0.75rem 0.9rem; font-size: 0.95rem;
}
.suggestions { display: none; margin-top: 0.55rem; border: 1px solid var(--gb-border); border-radius: 12px; background: #fff; overflow: hidden; }
.suggestions button { width: 100%; text-align: left; border: 0; background: #fff; padding: 0.65rem 0.8rem; cursor: pointer; }
.suggestions button:hover { background: var(--gb-cream-100); }
.filter-panel { display: none; margin-top: 0.75rem; padding-top: 0.7rem; border-top: 1px solid var(--gb-border); }
.toggle-group { display: inline-flex; background: var(--gb-cream-100); border-radius: 999px; padding: 0.2rem; }
.toggle-group button { border: 0; background: transparent; border-radius: 999px; padding: 0.48rem 0.88rem; font-weight: 700; cursor: pointer; color: var(--gb-muted); }
.toggle-group button.active { background: #fff; color: var(--gb-green-900); box-shadow: var(--shadow-soft); }
.map-box { height: 360px; border-radius: var(--radius-lg); background: linear-gradient(150deg, #d8eadf, #f1e6d5); border: 1px solid var(--gb-border); position: relative; overflow: hidden; }
.map-pin { position: absolute; width: 14px; height: 14px; border-radius: 50%; background: var(--gb-green-700); border: 2px solid #fff; box-shadow: var(--shadow-soft); }
.results-list { display: grid; gap: 0.85rem; }
.result-item { background: #fff; border: 1px solid var(--gb-border); border-radius: var(--radius-md); padding: 0.9rem; }

.cookie-banner {
  position: fixed; left: 1rem; right: 1rem; bottom: 1rem; z-index: 40;
  background: #fff; border: 1px solid var(--gb-border); border-radius: 14px; box-shadow: var(--shadow-card);
  padding: 0.9rem; display: flex; justify-content: space-between; gap: 1rem; align-items: center;
}

.site-footer { margin-top: 4rem; background: #102a1e; color: #e9f0ea; }
.footer-top { padding: 2.2rem 0; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 1rem; }
.footer-col h4 { margin: 0 0 0.55rem; font-family: 'DM Sans', sans-serif; }
.footer-col a { display: block; color: #dce6df; padding: 0.2rem 0; font-size: 0.93rem; }
.footer-col a:hover { color: #fff; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.16); padding: 1rem 0 1.3rem; color: #c9d4cc; font-size: 0.88rem; display: flex; justify-content: space-between; gap: 1rem; }
.footer-accordion-toggle { display: none; }

@media (max-width: 980px) {
  .hero, .grid-3 { grid-template-columns: 1fr; }
  .menu-layout { grid-template-columns: 1fr; }
  .sidebar { position: static; }
  .footer-top { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 760px) {
  .mobile-toggle { display: inline-flex; }
  .nav-links {
    display: none; position: absolute; left: 0.9rem; right: 0.9rem; top: 68px; background: #fff;
    border: 1px solid var(--gb-border); border-radius: 14px; padding: 0.6rem; box-shadow: var(--shadow-card);
    flex-direction: column; align-items: stretch;
  }
  .nav-links.open { display: flex; }
  .header-actions .btn-soft { display: none; }
  .grid-2, .menu-items, .search-row { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid rgba(255,255,255,0.15); }
  .footer-col h4 { margin: 0; padding: 0.9rem 0; display: flex; justify-content: space-between; align-items: center; cursor: pointer; }
  .footer-col .footer-links { display: none; padding-bottom: 0.8rem; }
  .footer-col.open .footer-links { display: block; }
  .footer-accordion-toggle { display: inline; font-size: 1.15rem; }
  .cookie-banner { flex-direction: column; align-items: stretch; }
}
EOF

